const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const callStatus = (body.CallStatus || '').toLowerCase();
const missedStatuses = ['no-answer', 'busy'];
if (!missedStatuses.includes(callStatus)) return [];
const callerPhone = body.From || body.Caller || '';
if (!callerPhone) return [];
return [{ json: {
  source: 'Phone',
  phone: callerPhone,
  callStatus: body.CallStatus || '',
  callSid: body.CallSid || '',
  calledNumber: body.To || body.Called || '',
  status: 'New'
}}];

const lead = $json;

// Static SMS — no AI. Claude was removed after testing (simpler, faster, zero cost).
const smsMessage = "Sorry we missed your call. Please complete our quick roofing request form so we can review your project and contact you promptly: https://roofing.valfin.com/request";

return [{
  json: {
    ...lead,
    message: smsMessage
  }
}];

const lead = $('Build SMS Request').first().json;

// Passes source='Phone' and logSummary='Missed call — auto-SMS sent' to CRM Adapter.
// These exact strings trigger skipLeadCreation=true in the adapter,
// so no Lead record is created — only a Communication Log entry.
return [{
  json: {
    source: 'Phone',
    phone: lead.phone,
    status: 'New',
    logChannel: 'Phone',
    logDirection: 'Inbound',
    logHandler: 'System',
    logSummary: 'Missed call — auto-SMS sent',
    logNotes:
      'CallStatus: ' + (lead.callStatus || '') +
      ' | CallSid: ' + (lead.callSid || '') +
      ' | SMS sent: ' + (lead.message || '')
  }
}];
